  ui_story_5023_50230101_52_dialog_content = "Pero... Pero... Esa mujer canosa da tanto miedo...",
  ui_story_5023_50230101_53_dialog_content = "Niña, esta aterradora mujer canosa acaba de salvarte la vida.",
  ui_story_5023_50230101_54_dialog_content = "¡No te acerques más!",
  ui_story_5023_50230101_55_dialog_content = "Je, intenta detenerme.",
  ui_story_5023_50230101_56_dialog_content = "Por favor... ¡Por favor, no lastimes a mi hermano!",
  ui_story_5023_50230101_57_dialog_content = "¡Necesitaba dinero para tratar mi enfermedad y terminó siendo engañado para unirse al Blue Lion Guild!",
  ui_story_5023_50230101_58_dialog_content = "Cada vez que sale a trabajar, estos hombres de aspecto aterrador me encierran en el almacén...",
  ui_story_5023_50230101_59_dialog_content = "¡Si te debe algo, te prometo que te lo devolveré!",
  ui_story_5023_50230101_60_dialog_content = "Por favor... No lastimes a mi hermano...",
  ui_story_5023_50230101_61_dialog_content = "...",
  ui_story_5023_50230101_62_dialog_content = "Los trucos sucios como usar a los seres queridos como rehenes definitivamente se alinean con el comportamiento que se espera de esos gremios de tercera categoría.",
  ui_story_5023_50230101_63_dialog_content = "¿Nunca has pensado en lo que le pasaría a tu hermana si murieras?",
  ui_story_5023_50230101_64_dialog_content = "... YO...",
  ui_story_5023_50230101_65_dialog_content = "En lugar de actuar con descaro y lanzarse de cabeza hacia la muerte, debes usar tu cerebro y descubrir cómo sobrevivir con ella.",
  ui_story_5023_50230101_66_dialog_content = "Toma esto.",
  ui_story_5023_50230101_67_dialog_content = "¿Qué hay en esta bolsa?",
  ui_story_5023_50230101_68_dialog_content = "¿Ni siquiera puedes distinguir el sonido de Nightium? Cómo tu estúpido Gremio de Leones Azules logras llegar a Umbraton está más allá de mí.",
  ui_story_5023_50230101_69_dialog_content = "Es mi responsabilidad asegurarme de que la riqueza inmerecida en sus manos vaya a donde pertenece.",
  ui_story_5023_50230101_70_dialog_content = "Eventualmente, encontraré lo que estoy buscando. Cuando llegue ese momento, me imagino que tus superiores vendrán por ti.",
  ui_story_5023_50230101_71_dialog_content = "No es demasiado tarde para correr.",
  ui_story_5023_50230101_72_dialog_content = "¡Espera!",
  ui_story_5023_50230101_73_dialog_content = "... ¿Por qué me ayudas?",
  ui_story_5023_50230101_74_dialog_content = "Eso no es de tu interés. Date prisa antes de que cambie de opinión.",
  ui_story_5023_50230101_75_dialog_content = "<color=#828282>¡Bam!</color>",
  ui_story_5023_50230101_76_dialog_content = "¡Una explosión! ¡Hubo un sonido de explosión en las cercanías del almacén! ¡Todos vayan y echen un vistazo!",
  ui_story_5023_50230101_76X_dialog_content = "Bonito... Todos los guardias se retiran. No está mal. Supongo que el chico es más brillante de lo que pensaba.",
  ui_story_5023_50230101_77_dialog_content = "...",
  ui_story_5023_50230101_78_dialog_content = "Hermano, eh...",
  ui_story_5023_50230101_79_dialog_content = "Después de eso, Acer y yo corrimos de un lugar a otro con la ayuda del dinero. Azure me dio.",
  ui_story_5023_50230101_80_dialog_content = "No mucho después, se expuso la conspiración del Blue Lion Guild. El Señor de las Sombras se ocupó de ellos y finalmente nos liberamos de nuestros perseguidores.",
  ui_story_5023_50230101_81_dialog_content = "Pregunté por la señorita Azure por todas partes y me enteré de un montón de hechos heroicos que realizó, lo que me llevó a querer unirme a Rediesel Wrench.",
  ui_story_5023_50230101_82_dialog_content = "Oh, ¿así es como perdiste tu billetera esa vez que fuiste a Umbraton a comprar un collar para el Franz de Kafka?",
  ui_story_5023_50230101_83_dialog_content = "¿Por qué eso importa? Traje el cargamento y vendí la inteligencia por un buen precio, ¿no?",
  ui_story_5023_50230101_84_dialog_content = "Nos diste una segunda oportunidad en la vida y quiero usarla para pagar tu amabilidad.",
  ui_story_5023_50230101_85_dialog_content = "No hay necesidad. Disfruto estar solo, y no necesito la gratitud de nadie.",
  ui_story_5023_50230101_86_dialog_content = "Solo necesito mi auto, mi arma y... tal vez también un perro como el de Kafka.",
  ui_story_5023_50230101_87_dialog_content = "Extrañar Azure, por favor acéptame como tu perro entonces!",
  ui_story_5023_50230101_88_dialog_content = "¡Espera un segundo!",
  ui_story_5023_50230101_89_dialog_content = "¡Cuida tu lenguaje! ¡Tenemos menores aquí!",
  ui_story_5023_50230101_90_dialog_content = "¿Mmm? ¿Dijo algo que no es apto para menores?",
  ui_story_5023_50230101_91_dialog_content = "¡Ya no somos niños! ¡Díganos lo que quiere decir, díganos lo que quiere decir!",
  ui_story_5023_50230101_92_dialog_content = "Lo escuché mencionar un perro... ¿Hay un cachorro perdido?",
  ui_story_5023_50230101_93_dialog_content = "Así es. Antes de conocer a la señorita Azure, Estaba perdido en la vida, como un extraviado—",
  ui_story_5023_50230101_94_dialog_content = "¡Ejem!",
  ui_story_5023_50230101_95_dialog_content = "¡Te dije que cuidaras tu lenguaje!",
  ui_story_5023_50230101_96_dialog_content = "¡Ustedes tres! ¡Ve a lavarte las manos, la cena está casi lista!",
  ui_story_5023_50230101_97_dialog_content = "Multa...",
  ui_story_5023_50230101_98_dialog_content = "Qué joven tan sencillo. Interesante.",
  ui_story_5023_50230101_99_dialog_content = "Honestamente, ¿dejarías de seducir a los jóvenes de izquierda a derecha? Cuando no pueden encontrarte, se convierten en mi problema.",
  ui_story_5023_50230101_100_dialog_content = "U-Um... Azure.",
  ui_story_5023_50230101_101_dialog_content = "Ah, es Acer, ¿no? ¿Cómo estás? ¿Te sientes mejor?",
  ui_story_5023_50230101_102_dialog_content = "Sí. Ahora estoy bien...",
  ui_story_5023_50230101_103_dialog_content = "Además, aprendí muchas cosas mientras viajaba con las caravanas e incluso ahorré algo de dinero ayudando a los comerciantes...",
  ui_story_5023_50230101_104_dialog_content = "N-No es suficiente para pagar señorita Azure te devuelvo el dinero que nos prestaste, pero seguiré trabajando duro!",
  ui_story_5023_50230101_105_dialog_content = "Nunca tuve la intención de que... No importa.",
  ui_story_5023_50230101_106_dialog_content = "Al final del día, los Rediesel Wrench son solo un grupo de pueblerinos incultos que se involucran en peleas día tras día.",
  ui_story_5023_50230101_107_dialog_content = "Creo que te irá mejor si trabajas de camarera en el Gusano de Arena Retorcido. Conozco bien al dueño y me aseguraré de que te trate bien.",
  ui_story_5023_50230101_108_dialog_content = "En cuanto a tu hermano... dudo que pueda manejar un golpe de Roy, pero todavía tiene suficiente para trabajar en la seguridad allí.",
  ui_story_5023_50230101_109_dialog_content = "Una vez que domines todos sus combinados especiales, abre una taberna en nuestro Oasis.",
  ui_story_5023_50230101_110_dialog_content = "¡Está bien!",
  ui_story_5023_50230101_111_dialog_content = "Realmente vas a hacer todo lo posible para conseguir bebidas gratis...",
  ui_story_5023_50230101_112_dialog_content = "Tengo tanta hambre de repente. ¿Que hay para cenar?",
  ui_story_5023_50230101_113_dialog_content = "Ese fue un cambio de tema muy pobre.",
  ui_story_5023_50230101_114_dialog_content = "... Hice camello al vapor con cebolla de desierto.",
  ui_story_5023_50230201_1_dialog_content = "...",
  ui_story_5023_50230201_2_dialog_content = "... Excelente. Él no está cerca. Ahora es el tiempo.",
  ui_story_5023_50230201_3_dialog_content = "Azure?",
  ui_story_5023_50230201_4_dialog_content = "... ¡Maldita sea, me atraparon!",
  ui_story_5023_50230201_5_dialog_content = "¿Por qué estás cojeando? ¿Estás herido?",
  ui_story_5023_50230201_6_dialog_content = "Cállate... Silencio. no dejes Roy escucharte",
  ui_story_5023_50230201_7_dialog_content = "Nunca volveré a ganar una discusión contra él si descubre que me lesioné durante una emboscada.",
  ui_story_5023_50230201_8_dialog_content = "Entonces, ¿estás... tratando de robar suministros de primeros auxilios? Te ayudaré a tratar tus heridas.",
  ui_story_5023_50230201_9_dialog_content = "No, son solo heridas superficiales. Además, vas a salir con Sinsa, ¿no es así?",
  ui_story_5023_50230201_10_dialog_content = "Pero tengo licor.",
  ui_story_5023_50230201_11_dialog_content = "... Negociar.",
  ui_story_5023_50230201_12_dialog_content = "Bueno, no es tan malo como parece. La mayor parte de la sangre no es tuya, así que deberías estar bien.",
  ui_story_5023_50230201_13_dialog_content = "Siento que no recibo tanto cuidado o atención de usted en estos días. ¿Ya no me amas?",
  ui_story_5023_50230201_14_dialog_content = "¿Te golpeaste la cabeza por casualidad? Porque lo parece. Tal vez debería llamar Roy para echar un vistazo.",
  ui_story_5023_50230201_15_dialog_content = "estaba bromeando ¡Que era una broma!",
  ui_story_5023_50230201_16_dialog_content = "Esto probablemente va a doler un poco. Tengan paciencia conmigo.",
  ui_story_5023_50230201_17_dialog_content = "Es raro que caigas en la trampa de alguien.",
  ui_story_5023_50230201_18_dialog_content = "Deberías haber visto cómo terminaron mis oponentes.",
  ui_story_5023_50230201_19_dialog_content = "Creo que los buitres ya deben estar alimentándose de los restos de esos humildes mocosos.",
  ui_story_5023_50230201_20_dialog_content = "El líder del grupo afirmó ser el sobreviviente de una pandilla que Rediesel Wrench había eliminado en el pasado.",
  ui_story_5023_50230201_21_dialog_content = "¿Qué pandilla?",
  ui_story_5023_50230201_22_dialog_content = "Yo hice la misma pregunta.",
  ui_story_5023_50230201_23_dialog_content = "Nos hemos librado de tantas pandillas a lo largo de los años, ¿cómo se supone que vamos a recordar todos sus nombres?",
  ui_story_5023_50230201_24_dialog_content = "Ah, pero recuerdo el Corredor de la Muerte. Tu enfrentamiento con su líder fue realmente maravilloso.",
  ui_story_5023_50230201_25_dialog_content = "Eso es todo... Después de todo, han pasado tantos años.",
  ui_story_5023_50230201_26_dialog_content = "Deberías haber visto la mirada en la cara del tipo calvo cuando le dije que no podía recordar a su pandilla en absoluto, fue gracioso.",
  ui_story_5023_50230201_27_dialog_content = "Sin embargo... Bueno. Porque nos conocía...",
  ui_story_5023_50230201_28_dialog_content = "Sabía cómo atraerme con información sobre los sobrevivientes de Balsa.",
  ui_story_5023_50230201_29_dialog_content = "Ya veo. Es lo único que investigarías incluso sabiendo que podría ser una trampa.",
  ui_story_5023_50230201_30_dialog_content = "No hay riesgo que no esté dispuesto a correr si existe la posibilidad de que me lleve hasta mi hermano.",
  ui_story_5023_50230201_31_dialog_content = "¿No deberías llevar a alguien contigo en momentos como estos?",
  ui_story_5023_50230201_32_dialog_content = "Ay. Tómatelo con calma, ¿quieres?",
  ui_story_5023_50230201_33_dialog_content = "Tus habilidades de enfermería no han mejorado en absoluto.",
  ui_story_5023_50230201_34_dialog_content = "Sabes que no me lesiono a menudo, como tú. Rara vez tengo la oportunidad de practicar.",
  ui_story_5023_50230201_35_dialog_content = "Lo cual es algo bueno, por cierto.",
  ui_story_5023_50230201_36_dialog_content = "Muy bien, he terminado.",
  ui_story_5023_50230201_37_dialog_content = "Aquí tienes. Algunas cosas buenas de Jomu. Lo he estado guardando solo para ti. ¿Con hielo?",
  ui_story_5023_50230201_38_dialog_content = "Mmm... ¡Hermoso!",
  ui_story_5023_50230201_39_dialog_content = "Y sentado aquí, obtienes una vista panorámica del Oasis. Me encanta.",
  ui_story_5023_50230201_40_dialog_content = "Su hombro es tan cómodo para apoyarse en él.",
  ui_story_5023_50230201_41_dialog_content = "...",
  ui_story_5023_50230201_42_dialog_content = "Tengo que vivir, aunque solo sea por estos momentos. Para sobrevivir, y volver.",
  ui_story_5023_50230201_43_dialog_content = "Mientras sepas eso.",
  ui_story_5023_50230201_44_dialog_content = "¡Bebamos al contenido de nuestro corazón hoy!",
  ui_story_5023_50230201_45_dialog_content = "Hm... con mucho gusto.",
  ui_story_5023_50230301_1_dialog_content = "Los equipos están listos, ingredientes y premios... confirmados.",
  ui_story_5023_50230301_2_dialog_content = "Fantástico. Finalmente tenemos algo más que el Polvo de Proteína de Insecto de Jomu y muñecos al azar este año como premios.",
  ui_story_5023_50230301_3_dialog_content = "me pregunto dónde Jomu es...",
  ui_story_5023_50230301_4_dialog_content = "Tiny One lo colgó por ocupar demasiado espacio en el almacén, probablemente esté pidiendo clemencia en este momento.",
  ui_story_5023_50230301_5_dialog_content = "Odi, ¡estás de vuelta! ¿Están establecidos los puntos de comunicación para todas las etapas?",
  ui_story_5023_50230301_6_dialog_content = "Por supuesto. Pedazo de pastel.",
  ui_story_5023_50230301_7_dialog_content = "¿Tienes idea de cuántas fallas técnicas estúpidas tengo que enfrentar por todos estos idiotas todos los días?",
  ui_story_5023_50230301_8_dialog_content = "¡Más de la mitad de sus problemas siempre se solucionan con solo reiniciar! Francamente, son sus cerebros los que necesitan servicio—",
  ui_story_5023_50230301_9_dialog_content = "Eh... lo siento. Hablé demasiado.",
  ui_story_5023_50230301_10_dialog_content = "Probablemente eres el único más ocupado que yo en todo Rediesel Wrench.",
  ui_story_5023_50230301_11_dialog_content = "Cuando Tiny One, Fleur y todos tenemos las manos llenas, siempre eres tú a quien llamamos para pedir ayuda...",
  ui_story_5023_50230301_12_dialog_content = "Jaja, no soy un profesional. Considero un milagro que no termine causando más problemas.",
  ui_story_5023_50230301_13_dialog_content = "Ahí tienes, Roy! Se realiza el mantenimiento y las pruebas de Lepidoz.",
  ui_story_5023_50230301_14_dialog_content = "Con tanto redisel en la barriga, Lepidoz debería poder seguir a nuestros concursantes hasta el final de la carrera sin ningún problema.",
  ui_story_5023_50230301_15_dialog_content = "que útil Odi también está aquí! Tenemos algunas cosas que verificar con usted con respecto a la configuración de comunicación por radio de Lepidoz...",
  ui_story_5023_50230301_16_dialog_content = "Roy!",
  ui_story_5023_50230301_17_dialog_content = "¿Qué pasa, líder?",
  ui_story_5023_50230301_17X_dialog_content = "¡Wow!",
  ui_story_5023_50230301_18_dialog_content = "¿Puedes evitar que Zeta agregue tantos detalles extraños a mi personaje?",
  ui_story_5023_50230301_19_dialog_content = "No me importa ser un berserker, pero ¿por qué tengo que estar \"tres veces divorciado\"?",
  ui_story_5023_50230301_20_dialog_content = "Er, retrocede un poco primero, ¿quieres? Los dos viejos parados con las caras tan juntas vamos a montar una escena.",
  ui_story_5023_50230301_21_dialog_content = "¡No soy un viejo!",
  ui_story_5023_50230301_22_dialog_content = "Claro, claro, dale un par de años más.",
  ui_story_5023_50230301_23_dialog_content = "De todos modos, parece que estás haciendo un buen papel para Zeta, pero no estás contento con tu papel.",
  ui_story_5023_50230301_24_dialog_content = "No a todos nos gusta andar respondiendo a lo que Zeta nos llame, a diferencia de algunas personas... Princesa.",
  ui_story_5023_50230301_25_dialog_content = "¡No me malinterpretes! Encuentro el papel de princesa muy desafiante. Definitivamente uno de los tres personajes más difíciles de interpretar.",
  ui_story_5023_50230301_26_dialog_content = "Si pudieras cambiar tu personalidad, ¿cuál elegirías? No me digas que usarías a Shinnosuke...",
  ui_story_5023_50230301_27_dialog_content = "Todavía no he usado esas historias como cuentos para dormir para los niños.",
  ui_story_5023_50230301_28_dialog_content = "Zeta es fácilmente influenciable. Si lo hago, no tardará mucho en cambiar tu papel por el de un viajero errante del Lejano Oriente empuñando una espada demoníaca.",
  ui_story_5023_50230301_29_dialog_content = "... ¿También has leído esa serie?",
  ui_story_5023_50230301_30_dialog_content = "¿Estás bromeando? Todas las fortalezas lo saben.",
  ui_story_5023_50230301_31_dialog_content = "Parece que compraste un montón de copias para enviárselas a la gente y luego los perseguiste obsesivamente preguntándoles sobre sus personajes favoritos.",
  ui_story_5023_50230301_32_dialog_content = "Así es, pero me haces sonar tan...",
  ui_story_5023_50230301_33_dialog_content = "\"¡Mataré a mil villanos en este mundo para mantener a mi hermana a salvo por el resto de su vida!\"",
  ui_story_5023_50230301_34_dialog_content = "¡No tienes que gritarlo!",
  ui_story_5023_50230301_35_dialog_content = "¿De qué hay que avergonzarse? No olvides que he leído toda la poesía que escribiste cuando eras niño. Esos eran aún más...",
  ui_story_5023_50230301_36_dialog_content = "Por cierto, estaba limpiando el almacén el otro día y encontré algunas colecciones de poesía más.",
  ui_story_5023_50230301_37_dialog_content = "¡¿Qué?!",
  ui_story_5023_50230301_38_dialog_content = "No te atrevas a mostrárselos Azure! ¡No tienes idea de cuánto tiempo se burló de mí después!",
  ui_story_5023_50230301_39_dialog_content = "Ah ah ah. Después de todos estos años, todavía no sabes cómo manejarla.",
  ui_story_5023_50230301_40_dialog_content = "Mmm...",
  ui_story_5023_50230301_41_dialog_content = "Esta es una oportunidad extremadamente rara. ¿Quieres hacer equipo con Azure para el rally de este año?",
  ui_story_5023_50230301_42_dialog_content = "A veces realmente no puedo decir si estás bromeando o no... ¿es esto lo que llamas terapia de exposición?",
  ui_story_5023_50230301_43_dialog_content = "Pero además Azure, quién más es más adecuado para mostrar PlayerName las técnicas de carreras de la Rediesel Wrench?",
  ui_story_5023_50230301_44_dialog_content = "... Tienes un punto.",
  ui_story_5023_50230301_45_dialog_content = "Pero primero, dame esas colecciones de poesía que encontraste.",
  ui_story_5023_50230301_46_dialog_content = "Hmm... ¿Qué debo hacer?",
  ui_story_5023_50230301_47_dialog_content = "Ya sabes cómo funcionan las cosas en Rediesel Wrench: primero en llegar, primero en servir, buscadores, guardianes.",
  ui_story_5023_50230301_48_dialog_content = "A menos, por supuesto, que me estés ordenando como mi líder... o si puedes quitármelos por la fuerza—",
  ui_story_5023_50230301_49_dialog_content = "... ¡Entonces no me voy a contener!",
  ui_story_5023_50230301_50_dialog_content = "Awww... que miedo.",
  ui_story_5023_50230301_51_dialog_content = "no es PlayerName ¿Esperando por ti? No es agradable hacer esperar al invitado.",
  ui_story_5023_50230301_52_dialog_content = "Es demasiado tarde para retirar tus palabras, Roy.",
  ui_story_5023_50230301_53_dialog_content = "¿Cambiar de opinión? ¡Nunca! Tienes un minuto. Llévate este bloc de notas y los poemas serán tuyos.",
  ui_story_5023_50230301_54_dialog_content = "De lo contrario, considere seriamente unirse a la carrera con Azure.",
  ui_story_5023_50230301_55_dialog_content = "Está tan harta de mis regaños. Uno de ustedes podría comunicarse con ella...",
  ui_story_5023_50230301_56_dialog_content = "¿Dijiste algo?",
  ui_story_5023_50230301_57_dialog_content = "Ahh... Nada.",
  ui_story_5023_50230301_58_dialog_content = "Le quedan 50 segundos, líder.",
  ui_story_5023_50230301_59_dialog_content = "¡Eso es hacer trampa!",
  ui_story_5023_50230301_60_dialog_content = "Ay... Me duele todo el cuerpo... Tiny One es despiadado...",
  ui_story_5023_50230301_61_dialog_content = "¿Mmm? ¿Una pelea?",
  ui_story_5023_50230301_62_dialog_content = "¡Guau! ¡Esquivó la llave inglesa del jefe y se fue tan rápido!",
  ui_story_5023_50230301_63_dialog_content = "Roy definitivamente no es alguien con quien quieras meterte... ¿Qué pasó con ellos de todos modos?",
  ui_story_5023_50230301_64_dialog_content = "¿Eh? No estaba prestando atención. Será mejor que te ocupes de tu cabeza hinchada antes de empezar a entrometerte en los asuntos de otras personas. Realmente, nunca aprendes la lección.",
  ui_story_5023_50230301_65_dialog_content = "Escuché Zeta. Y algo sobre agarrar un bloc de notas en un minuto. ...Eso es todo.",
  ui_story_5023_50230301_66_dialog_content = "Estoy dispuesto a apostar un kit de herramientas a que en una batalla de habilidad en lugar de resistencia, Boss no tiene ninguna posibilidad.",
  ui_story_5023_50230301_67_dialog_content = "Estoy fuera. No soy estúpido.",
  ui_story_5023_50230301_68_dialog_content = "Mmm. Tengo un buen titular para el Umbraton Daily.",
  ui_story_5023_50230301_69_dialog_content = "\"¡Conflicto entre el líder de Rediesel Wrench y el miembro sénior por la capacitación de nuevos talentos!\"",
  ui_story_5023_50230301_70_dialog_content = "Me pregunto cuánto pagaría la gente de Nightium por leer eso...",
  ui_story_5023_50230401_1_dialog_content = "¿Realmente no hay otra opción?",
  ui_story_5023_50230401_2_dialog_content = "Vamos, confía en mí en esto. Red Scorpion Pie es excelente.",
  ui_story_5023_50230401_3_dialog_content = "Como eres un VIP, el chef lo hizo especial solo para ti. El tuyo no solo tiene Deep Fried Flare Scorpion, sino que también incluye una serpiente de anillo carmesí asada adicional.",
  ui_story_5023_50230401_4_dialog_content = "¿Esto pretende ser un estímulo?",
  ui_story_5023_50230401_5_dialog_content = "¡Ambos me suenan mortales!",
  ui_story_5023_50230401_6_dialog_content = "¡No tengas miedo! ¡Saca la cabeza y el trasero y disfruta!",
  ui_story_5023_50230401_7_dialog_content = "Los más aptos sobreviven. La regla más fuerte. Así es como funciona la vida en el desierto.",
  ui_story_5023_50230401_8_dialog_content = "Consumes este pastel con respeto por las vidas de las criaturas derrotadas que solían hacerlo, sus vidas se vuelven parte de tu carne y sangre, y así la vida continúa.",
  ui_story_5023_50230401_9_dialog_content = "Su discurso es muy poético y contundente, pero yo...",
  ui_story_5023_50230401_10_dialog_content = "Joven, ¿qué tal una sopa de aperitivo?",
  ui_story_5023_50230401_11_dialog_content = "¡Gracias!",
  ui_story_5023_50230401_12_dialog_content = "*Tos*... ¿Qué diablos es esto?",
  ui_story_5023_50230401_13_dialog_content = "¡Sopa de gusanos de arena y langostas!",
  ui_story_5023_50230401_14_dialog_content = "Wow, qué nombre tan brutalmente directo.",
  ui_story_5023_50230401_15_dialog_content = "Espera, lo he escuchado antes... ¿estaba en un libro?",
  ui_story_5023_50230401_16_dialog_content = "Ja, eres bastante culto!",
  ui_story_5023_50230401_17_dialog_content = "Este es un famoso manjar del desierto. Aparentemente, algunos chefs de otras regiones han tratado de reproducirlo incluso cuando no pudieron conseguir todos los ingredientes esenciales.",
  ui_story_5023_50230401_18_dialog_content = "\"Agregue pimentón ahumado y langostas fritas. Cúbralo con una cucharada de salsa picante...\"",
  ui_story_5023_50230401_19_dialog_content = "¿Por casualidad sirves Sandstone Rice?",
  ui_story_5023_50230401_20_dialog_content = "¿Cómo sabes el plato especial del dueño? ¡Ni siquiera está en el menú!",
  ui_story_5023_50230401_21_dialog_content = "Supongo que realmente debe disfrutar de nuestra cocina del desierto. Consíguele otra botella de leche de camella.",
  ui_story_5023_50230401_22_dialog_content = "¿Este restaurante es propiedad del tío Johnny?",
  ui_story_5023_50230401_23_dialog_content = "¿Oh? ¿También has visto la Receta Rediesel?",
  ui_story_5023_50230401_24_dialog_content = "¡No puedes hablar en serio!",
  ui_story_5023_50230401_25_dialog_content = "He querido conocerlo desde que leí su libro...",
  ui_story_5023_50230401_26_dialog_content = "¿Por qué no dijiste algo antes? Actualmente, Johnny está viajando por el mundo en busca de nuevas inspiraciones.",
  ui_story_5023_50230401_27_dialog_content = "No regresará para el Blazing Rally.",
  ui_story_5023_50230401_28_dialog_content = "Johnny es uno de los pocos miembros aquí que no está tan interesado en las carreras.",
  ui_story_5023_50230401_29_dialog_content = "Su corazón y su alma están llenos de alimento.",
  ui_story_5023_50230401_30_dialog_content = "Apuesto a que actualmente está al acecho fuera de una guarida de Eclipsite, en busca de sabrosos Eclipsites.",
  ui_story_5023_50230401_31_dialog_content = "¿Los eclipses son comestibles?",
  ui_story_5023_50230401_32_dialog_content = "Ahora que lo pienso, afirmó ser un catador de carne de Eclipsite en su libro...",
  ui_story_5023_50230401_33_dialog_content = "Es una pena que no puedas reunirte con él esta vez. Pero la comida será... ¿qué era de nuevo?",
  ui_story_5023_50230401_34_dialog_content = "Ah bien. La comida los conectará a los dos más allá del tiempo y el espacio.",
  ui_story_5023_50230401_35_dialog_content = "Por cierto, no me lo saqué del culo. Es lo que siempre dice Johnny.",
  ui_story_5023_50230401_36_dialog_content = "Tiene planes de imprimirlo en la portada de su secuela de Receta Rediesel.",
  ui_story_5023_50230401_37_dialog_content = "(Vice también le encanta probar ingredientes inusuales... pero sus platos se parecen más a armas letales que a comida real).",
  ui_story_5023_50230401_38_dialog_content = "(¡Pero esta es mi oportunidad de experimentar todas las cosas emocionantes del libro!)",
  ui_story_5023_50230401_39_dialog_content = "(En el peor de los casos, mi viaje termina con una intoxicación alimentaria la noche anterior a la carrera...)",
  ui_story_5023_50230401_40_dialog_content = "¡Okey! ¡comeré!",
  ui_story_5023_50230401_41_dialog_content = "...",
  ui_story_5023_50230401_42_dialog_content = "(¡Ah! De alguna manera, todavía estoy vivo. Y...)",
  ui_story_5023_50230401_43_dialog_content = "... Esto... sabe bastante bien.",
  ui_story_5023_50230401_44_dialog_content = "¡Sí! ¡Te gusta!",
  ui_story_5023_50230401_45_dialog_content = "Sí. El escorpión es tan crujiente por fuera y muy tierno y jugoso por dentro. Y el condimento picante y ácido es para morirse...",
  ui_story_5023_50230401_46_dialog_content = "... ¡Escucha esas palabras elegantes! ¿Obtienes todo eso de los libros que lees?",
  ui_story_5023_50230401_47_dialog_content = "¿Yo se, verdad? A diferencia de nosotros. Solo somos buenos para llenarnos la cara y decir: \"¡Maldita sea, eso es algo bueno!\"",
  ui_story_5023_50230401_48_dialog_content = "Suspiro. Ojalá Johnny pudiera escuchar esto por sí mismo.",
  ui_story_5023_50230401_49_dialog_content = "... PlayerName.",
  ui_story_5023_50230401_50_dialog_content = "¿Si?",
  ui_story_5023_50230401_51_dialog_content = "¿Te interesaría probar y revisar todo lo que tiene el restaurante? Eso realmente haría feliz a Johnny.",
  ui_story_5023_50230401_52_dialog_content = "Err... sugiero que guardemos un poco para la próxima vez. Mis papilas gustativas están al límite por el día...",
  ui_story_5023_50230401_53_dialog_content = "La fiesta de celebración tendrá lugar al final de la carrera. No podrás obtener ningún segundo allí.",
  ui_story_5023_50230401_54_dialog_content = "¿En serio?",
  ui_story_5023_50230401_55_dialog_content = "(Estoy un poco decepcionado pero también un poco aliviado...)",
  ui_story_5023_50230401_56_dialog_content = "¡Oye, no te preocupes! Roy está a cargo de la fiesta de celebración.",
  ui_story_5023_50230401_57_dialog_content = "Será otra emocionante aventura para tus papilas gustativas, ¡casi tan emocionante como los platos de Johnny!",
  ui_story_5023_50230401_58_dialog_content = "¿Comer siempre es una aventura con Rediesel Wrench?",
  ui_story_5023_50230401_59_dialog_content = "Muy bien, debes tener sed después de tanto hablar.",
  ui_story_5023_50230401_60_dialog_content = "¡Bebe el jugo de fruta podrida de lengua de dragón y luego probaremos el menú secreto!",
  ui_story_5023_50230401_61_dialog_content = "Um... ¿Incluido el arroz de arenisca?",
  ui_story_5023_50230401_62_dialog_content = "(Va a ser una noche larga...)",
  ui_story_5023_50230501_1_dialog_content = "Hmm... yo... no puedo ver lo que hay delante...",
  ui_story_5023_50230501_2_dialog_content = "Esta voz... ¿Zeta? ¿Para qué es toda esta ropa?",
  ui_story_5023_50230501_3_dialog_content = "¡Guau!",
  ui_story_5023_50230501_4_dialog_content = "Debo recoger estos rápidamente.",
  ui_story_5023_50230501_5_dialog_content = "Emm... ¡Zeta está lavando ropa!",
  ui_story_5023_50230501_6_dialog_content = "¡Todos estos son míos!",
  ui_story_5023_50230501_7_dialog_content = "Jona, has visto la ropa y el sombrero que tenia colgado afuera?",
  ui_story_5023_50230501_8_dialog_content = "No.",
  ui_story_5023_50230501_9_dialog_content = "Espera... Vi a Zeta con un montón de ropa antes. Ella podría haber agarrado el tuyo por accidente.",
  ui_story_5023_50230501_10_dialog_content = "¿Cómo, cuando ella es la mitad de mi tamaño?",
  ui_story_5023_50230501_11_dialog_content = "No sé sobre eso. Algunas de tus blusas son bastante cortas. Me encantan, por cierto.",
  ui_story_5023_50230501_12_dialog_content = "Je... Por mucho que me gustaría quedarme y escuchar tus halagos, realmente tengo que ir a buscar a Zeta.",
  ui_story_5023_50230501_13_dialog_content = "Avanzar. No es como si estuviera celoso o algo así.",
  ui_story_5023_50230501_14_dialog_content = "Ugh... ¿esto... se supone que es así? ¡Lo que!",
  ui_story_5023_50230501_15_dialog_content = "¡Ay! O-Oh no! Incluso yo puedo decir que no está bien...",
  ui_story_5023_50230501_16_dialog_content = "¿Quizás lo limpie? ... ¡Es incluso peor ahora!",
  ui_story_5023_50230501_17_dialog_content = "De acuerdo a Barbara, maquillarse es como dibujar, pero por qué...",
  ui_story_5023_50230501_18_dialog_content = "¿Realmente tienes que preguntar? ¿Has olvidado lo terrible que eres dibujando?",
  ui_story_5023_50230501_19_dialog_content = "<size=45>¡Ahhh!</size>",
  ui_story_5023_50230501_20_dialog_content = "A-Azure? ¡¿Qué te trae por aquí?!",
  ui_story_5023_50230501_21_dialog_content = "Alto ahí. Esta es la base secreta de la heroína. Si el lacayo del diablo se abre paso a la fuerza...",
  ui_story_5023_50230501_22_dialog_content = "<size=45>¡Déjame terminar!</size>",
  ui_story_5023_50230501_23_dialog_content = "¿Mmm? ¿No deberías mirar a alguien a los ojos cuando les hablas?",
  ui_story_5023_50230501_24_dialog_content = "Um... u-uh... ¡Ejem! *tose* tengo un resfriado y no te lo quiero pasar...",
  ui_story_5023_50230501_25_dialog_content = "Dios mío, una enfermedad repentina, ¿eh? No me vengas con eso, idiota, no te enfermes.",
  ui_story_5023_50230501_26_dialog_content = "Date la vuelta por mí.",
  ui_story_5023_50230501_27_dialog_content = "<size=45>H-Espera! ¿Puedes prometer que no te reirás?</size>",
  ui_story_5023_50230501_28_dialog_content = "Sabes lo difícil que es hacerme reír.",
  ui_story_5023_50230501_29_dialog_content = "...",
  ui_story_5023_50230501_30_dialog_content = "No...",
  ui_story_5023_50230501_31_dialog_content = "¡Prometiste que no te reirías!",
  ui_story_5023_50230501_32_dialog_content = "Lo siento, oh gran heroína.",
  ui_story_5023_50230501_33_dialog_content = "Esperaba que fuera divertido pero esto supera todas mis expectativas. ¿Cómo puede alguien no reírse de esto?",
  ui_story_5023_50230501_34_dialog_content = "¡Tú!",
  ui_story_5023_50230501_35_dialog_content = "Ven. Límpiate la cara con esta toalla.",
  ui_story_5023_50230501_36_dialog_content = "...",
  ui_story_5023_50230501_37_dialog_content = "Así que dime qué está pasando, ¿por qué de repente te interesa el maquillaje?",
  ui_story_5023_50230501_38_dialog_content = "... ¡N-No hay razón!",
  ui_story_5023_50230501_39_dialog_content = "Bueno... ya ves, Barbara ¡Me dijo que esto funcionaría como un amuleto mágico que aumenta el poder de la heroína!",
  ui_story_5023_50230501_40_dialog_content = "¡Sí! ¡Eso es todo!",
  ui_story_5023_50230501_41_dialog_content = "¿Vaya? ¿De qué tipo de poder estamos hablando?",
  ui_story_5023_50230501_42_dialog_content = "Eh... ¿De qué tipo? mmm...",
  ui_story_5023_50230501_43_dialog_content = "Bueno, ciertamente no es inteligencia. Hmm... ¿podría ser poder carismático?",
  ui_story_5023_50230501_44_dialog_content = "¿Cómo te diste cuenta de eso? ¡Maldita sea! Absolute Zero Witch es incluso más fuerte de lo que pensaba...",
  ui_story_5023_50230501_45_dialog_content = "Yo solo... yo solo <size=30>quiero ser madura y elegante como tu...</size> ",
  ui_story_5023_50230501_46_dialog_content = "¿Eh? No puedo oírte.",
  ui_story_5023_50230501_47_dialog_content = "<size=45>¡Dije, quiero ser maduro y elegante como tú!</size>",
  ui_story_5023_50230501_48_dialog_content = "Porque eres tan fuerte y tan bonita y siempre llamas la atención de la gente sin tener que hacer ningún truco...",
  ui_story_5023_50230501_49_dialog_content = "¡Oooh! Nunca pensé que viviría para verte halagarme.",
  ui_story_5023_50230501_50_dialog_content = "¿Es por eso que me robaste la ropa y el sombrero?",
  ui_story_5023_50230501_51_dialog_content = "Sí... Pero son demasiado grandes para mí, ni siquiera puedo usarlos...",
  ui_story_5023_50230501_52_dialog_content = "¡Esta es una operación fallida, pero Zeta se convertirá en una mujer madura y glamorosa algún día! ¡Incluso mejor que tú!",
  ui_story_5023_50230501_53_dialog_content = "Oh, tú... aquí, siéntate aquí.",
  ui_story_5023_50230501_54_dialog_content = "¿Ah?",
  ui_story_5023_50230501_55_dialog_content = "Las mujeres no son maduras y elegantes por su forma de vestir.",
  ui_story_5023_50230501_56_dialog_content = "El maquillaje y la ropa son solo adornos superficiales.",
  ui_story_5023_50230501_57_dialog_content = "¡Pero siempre tienes a todos los chicos envueltos alrededor de tu dedo con tu apariencia y tu cuerpo!",
  ui_story_5023_50230501_58_dialog_content = "Eso... Bueno, no puedo negarlo, pero llamémoslo un pasatiempo inofensivo mío.",
  ui_story_5023_50230501_59_dialog_content = "No me importa que la gente comente bien mi figura.",
  ui_story_5023_50230501_60_dialog_content = "Pero me gano el respeto con mi arma, auto, habilidades de combate y cerebro.",
  ui_story_5023_50230501_61_dialog_content = "La atención y la idolatría de los demás no importan. Tienes que concentrarte en hacer aquello en lo que eres bueno y en lo que puedes hacer.",
  ui_story_5023_50230501_62_dialog_content = "... Dios mío, ¿cuándo he empezado a dar lecciones a los niños también...?",
  ui_story_5023_50230501_63_dialog_content = "Zeta entiende... pero tampoco realmente.",
  ui_story_5023_50230501_64_dialog_content = "¿Qué tipo de cosas puedo hacer?",
  ui_story_5023_50230501_65_dialog_content = "Solo soy bueno para hacer esas pequeñas tareas básicas de patrulla que Regina y los demás no pueden molestarse en hacer...",
  ui_story_5023_50230501_66_dialog_content = "No desprecies las tareas domésticas que contribuyen a ayudar a los aldeanos a expulsar a los eclipses.",
  ui_story_5023_50230501_67_dialog_content = "Son cruciales para desarrollar nuestra relación con todos los pueblos y ciudades del desierto.",
  ui_story_5023_50230501_68_dialog_content = "lloro cada vez que ayudo Roy cortar cebollas de baya, y ni siquiera puedo cortarlas bien...",
  ui_story_5023_50230501_69_dialog_content = "Pero tú lo ayudas a asegurarse de que todos los platos sepan bien cada vez, ¿no es así?",
  ui_story_5023_50230501_70_dialog_content = "Roy tiene miles de recetas en la cabeza pero su sentido del gusto apesta. Sufriríamos mucho sin ti.",
  ui_story_5023_50230501_71_dialog_content = "¡Parece que hay algunas cosas que puedo hacer bastante bien después de todo! ¡Y puedo hacerlo aún mejor!",
  ui_story_5023_50230501_72_dialog_content = "No sabía que podías ser tan amable y paciente...",
  ui_story_5023_50230501_73_dialog_content = "¿Hay algo que hayas olvidado?",
  ui_story_5023_50230501_74_dialog_content = "¿Ah?",
  ui_story_5023_50230501_75_dialog_content = "¿Qué pasa con esta pequeña huella de barro en mi chaqueta blanca? ¿Mmm?",
  ui_story_5023_50230501_76_dialog_content = "Err... Esto...",
  ui_story_5023_50230501_77_dialog_content = "Lavarlo de nuevo.",
  ui_story_5023_50230501_78_dialog_content = "¡N-No hay problema! ¡Mis amigos son muy buenos lavando ropa!",
  ui_story_5023_50230501_79_dialog_content = "No se limite a terminar el día arrojándolo a su máquina y haciéndolo girar con su Luminatics.",
  ui_story_5023_50230501_80_dialog_content = "Lavar únicamente a mano.",
  ui_story_5023_50230501_81_dialog_content = "Derecha. Ahora.",
  ui_story_5023_50230501_82_dialog_content = "*Sniff* Después de todo, las brujas dan miedo...",
  ui_story_5023_50230601_1_dialog_content = "Fue una noche escalofriante y completamente negra...",
  ui_story_5023_50230601_2_dialog_content = "Quizás porque el viento aullaba sobre la arena...",
  ui_story_5023_50230601_3_dialog_content = "O tal vez era la idea de los peligros ocultos que acechaban en la noche lo que me ponía ansioso.",
  ui_story_5023_50230601_4_dialog_content = "Di vueltas y vueltas inquieto en la cama, el insomnio se negaba a dejarme dormir.",
  ui_story_5023_50230601_5_dialog_content = "¿De quién fue la idea de contar historias de miedo junto a la fogata?",
  ui_story_5023_50230601_6_dialog_content = "¡Silenciar! ¡Escucha!",
  ui_story_5023_50230601_7_dialog_content = "Justo cuando iba y venía entre mis sueños y el mundo despierto, escuché una voz.",
  ui_story_5023_50230601_8_dialog_content = "Era la voz de una mujer, que venía desde afuera de mi habitación. Se sentía como susurros en el viento...",
  ui_story_5023_50230601_9_dialog_content = "Sin embargo, también se sentía como si estuviera justo a mi lado, respirando en mi oído.",
  ui_story_5023_50230601_10_dialog_content = "¿¿Eh??",
  ui_story_5023_50230601_11_dialog_content = "Me senté de inmediato. Y lo que vi en la tenue luz de la luna...",
  ui_story_5023_50230601_12_dialog_content = "¡Detenerse! N-No sigas...",
  ui_story_5023_50230601_13_dialog_content = "...era Rouge, Bently y Lompty durmiendo profundamente.",
  ui_story_5023_50230601_14_dialog_content = "... ¡¿Que demonios?! Tú llamas a esto— ¡Ay!",
  ui_story_5023_50230601_15_dialog_content = "no interrumpas Ruby cuando está leyendo su increíble epopeya, ¡Las aventuras de Great Explorer Ruby!",
  ui_story_5023_50230601_16_dialog_content = "Mi adrenalina estaba en su punto máximo.",
  ui_story_5023_50230601_17_dialog_content = "Porque de repente me di cuenta de que aunque tenía la intención de explorar todo Astra...",
  ui_story_5023_50230601_18_dialog_content = "Ni siquiera había explorado este lugar, ¡nuestra patria!",
  ui_story_5023_50230601_19_dialog_content = "¡¿Este espeluznante incidente tuvo lugar en el Oasis?! I... Fleur, ¡despertar! ¡Despertar!",
  ui_story_5023_50230601_20_dialog_content = "¡Aaaaaaaargh! ¡¿Por qué duerme como un muerto?!",
  ui_story_5023_50230601_21_dialog_content = "Ejem... No me importan las historias aburridas como esta. Todavía no he terminado con el entrenamiento de hoy, así que solo...",
  ui_story_5023_50230601_22_dialog_content = "¡No te quedes en el medio!",
  ui_story_5023_50230601_23_dialog_content = "Así que decidí seguir mi corazón y mis instintos de explorador...",
  ui_story_5023_50230601_24_dialog_content = "Partí de inmediato para ver qué podría estar escondiendo esta base familiar nuestra.",
  ui_story_5023_50230601_25_dialog_content = "¡Ay, ni siquiera sabía que habías pasado por todo eso!",
  ui_story_5023_50230601_26_dialog_content = "Parece que de ahora en adelante necesito mantener un ojo abierto mientras duermo para brindarle una mejor protección.",
  ui_story_5023_50230601_27_dialog_content = "Cuando salí por la puerta, la ya escasa luz de la luna quedó oscurecida por nubes oscuras, envolviendo la noche en una oscuridad total.",
  ui_story_5023_50230601_28_dialog_content = "El viento, que había estado aullando toda la noche, se detuvo. Podía escuchar el sonido de mi propio corazón latiendo en la quietud mortal.",
  ui_story_5023_50230601_29_dialog_content = "Chunda chunda...",
  ui_story_5023_50230601_30_dialog_content = "¡Y de repente! ¡Lo escuché de nuevo!",
  ui_story_5023_50230601_31_dialog_content = "La voz murmuraba algo, pero era apenas destilable...",
  ui_story_5023_50230601_32_dialog_content = "Espera, esto es un error tipográfico. Se supone que dice \"apenas perceptible\"... De todos modos.",
  ui_story_5023_50230601_33_dialog_content = "Era demasiado distante y apenas perceptible, no pude entender lo que decía en absoluto.",
  ui_story_5023_50230601_34_dialog_content = "Pero en ausencia del viento, pude averiguar de dónde venía el sonido...",
  ui_story_5023_50230601_35_dialog_content = "¡Estaba justo encima de mí! Sin embargo...",
  ui_story_5023_50230601_36_dialog_content = "¡La habitación de arriba siempre había estado vacía!",
  ui_story_5023_50230601_37_dialog_content = "¡Ahh!",
  ui_story_5023_50230601_38_dialog_content = "¡Chirrido!",
  ui_story_5023_50230601_39_dialog_content = "Pensé que las historias de Ruby eran tus favoritas, ¡no seas cobarde!",
  ui_story_5023_50230601_40_dialog_content = "¡No fue la historia, fue tu grito! ¡Me asustó muchísimo!",
  ui_story_5023_50230601_41_dialog_content = "Dos emociones chocaban dentro de mí en ese momento.",
  ui_story_5023_50230601_42_dialog_content = "El miedo a lo desconocido envió un escalofrío por mi espalda. Sin embargo, un flujo de adrenalina se disparó a través de mi cuerpo como electricidad, ¡hasta mi cerebro!",
  ui_story_5023_50230601_43_dialog_content = "Pero la emoción de explorar lo desconocido pronto suprimió la inquietud en mi corazón y me ayudó a mantener la calma.",
  ui_story_5023_50230601_44_dialog_content = "No dudé e inmediatamente comencé a subir las escaleras.",
  ui_story_5023_50230601_45_dialog_content = "Ruby! ¡Por favor, despiértame si esto vuelve a suceder!",
  ui_story_5023_50230601_46_dialog_content = "¡Este tipo de cosas son demasiado peligrosas para que las enfrentes solo!",
  ui_story_5023_50230601_47_dialog_content = "Me detuve fuera de la habitación vacía por un largo momento.",
  ui_story_5023_50230601_48_dialog_content = "La puerta normalmente cerrada estaba abierta solo un poco, pero no había luz adentro.",
  ui_story_5023_50230601_49_dialog_content = "En la abadía oscura... ejem.",
  ui_story_5023_50230601_50_dialog_content = "En el abismo oscuro, se sentía como si hubiera algo observándome.",
  ui_story_5023_50230601_51_dialog_content = "Por una fracción de segundo, quise darme la vuelta y salir corriendo. Sin embargo, el Sr. Jim de repente vino a mi mente.",
  ui_story_5023_50230601_52_dialog_content = "¡Mi ídolo, el Sr. Jim, el explorador legendario, definitivamente superaría su miedo y entraría al cuarto oscuro en busca de una respuesta!",
  ui_story_5023_50230601_53_dialog_content = "Y así, una cálida corriente de coraje llenó mi corazón y dispersó mi miedo.",
  ui_story_5023_50230601_54_dialog_content = "Puse una mano en el picaporte, y justo cuando estaba a punto de entrar, escuché de nuevo la voz.",
  ui_story_5023_50230601_55_dialog_content = "Esta vez, fue alto y claro—",
  ui_story_5023_50230601_56_dialog_content = "\"Gracias por tu compañía todos estos años. Pero todavía me siento tan solo a veces...\"",
  ui_story_5023_50230601_57_dialog_content = "Hay cosas que debo hacer.",
  ui_story_5023_50230601_58_dialog_content = "¿Q... qué significaba?",
  ui_story_5023_50230601_59_dialog_content = "Estaba a punto de acercarme cuando escuché el sonido de un arma siendo cargada.",
  ui_story_5023_50230601_60_dialog_content = "Sentí un deseo escalofriante de matar. Penetró la oscuridad y mi cuerpo como una daga afilada.",
  ui_story_5023_50230601_61_dialog_content = "Retrocedí paso a paso. Honestamente, no puedo recordar cómo regresé a mi cama.",
  ui_story_5023_50230601_62_dialog_content = "A la mañana siguiente, corrí a la habitación de arriba...",
  ui_story_5023_50230601_63_dialog_content = "Estaba vacío.",
  ui_story_5023_50230601_64_dialog_content = "Todavía hay muchas incógnitas en este mundo esperando ser descubiertas...",
  ui_story_5023_50230601_65_dialog_content = "¡Debe haber sido un fantasma! ¡Soy positivo!",
  ui_story_5023_50230601_66_dialog_content = "¡Si te hubieras quedado allí un momento más, esa voz te habría arrastrado al mundo de los fantasmas!",
  ui_story_5023_50230601_67_dialog_content = "¿El mundo de los fantasmas? Es eso cierto, Ruby?",
  ui_story_5023_50230601_68_dialog_content = "Lo siento, pero tu conjetura es tan buena como la mía.",
  ui_story_5023_50230601_69_dialog_content = "Fue una aventura fallida. La verdad permanece oculta en la densa niebla.",
  ui_story_5023_50230601_70_dialog_content = "Todavía tengo mucho espacio para crecer y mejorar como explorador...",
  ui_story_5023_50230601_71_dialog_content = "Si hay un mundo de fantasmas, sería interesante. ¿No creen ustedes?",
  ui_story_5023_50230601_72_dialog_content = "¡Sí! ¡Estaré al lado de Ruby pase lo que pase!",
  ui_story_5023_50230601_73_dialog_content = "¡Crujir!",
  ui_story_5023_50230601_74_dialog_content = "Puedo irme ahora...",
  ui_story_5023_50230601_75_dialog_content = "¡Achuu!",
  ui_story_5023_50230601_76_dialog_content = "¿Estás bien? ¿Necesitas una chaqueta?",
  ui_story_5023_50230601_77_dialog_content = "No tengo frio. Fue solo un estornudo al azar...",
  ui_story_5023_50230601_78_dialog_content = "Diría que es porque alguien está chismeando sobre mí, pero estás hablando de mí frente a mí, no a mis espaldas... así que debe ser el polvo.",
  ui_story_5023_50230601_79_dialog_content = "¿Seguro que no quieres unos días de descanso antes de volver a salir?",
  ui_story_5023_50230601_80_dialog_content = "He mantenido tu habitación intacta.",
  ui_story_5023_50230601_81_dialog_content = "No hay necesidad. Recibí un mensaje de un contacto a través de Courier Union con respecto a un lote de productos que estaba buscando.",
  ui_story_5023_50230601_82_dialog_content = "Bien entonces. Avísame si necesitas respaldo.",
  ui_story_5023_50230601_83_dialog_content = "Azure, cuídate. Ojo del Lince, cuida de ella.",
  ui_story_5023_50230601_84_dialog_content = "... ¿Por qué le hablas a mi arma?",
  ui_story_5023_50230601_85_dialog_content = "¿Mmm? ¿No le hablas a menudo cuando estás solo?",
  ui_story_5023_50230601_86_dialog_content = "Estoy fuera. Tengo la sensación de que este va a ser un viaje muy fructífero.",
  ui_story_5023_50230601_87_dialog_content = "Eso sería perfecto teniendo en cuenta la cantidad de dinero que siempre necesitamos para las reparaciones después del Blazing Rally...",
  ui_story_5023_50230601_88_dialog_content = "Feliz cacería."
}
return config
